local ECSComponent = import("Frame.ECS.ECSComponent")
---@class PhoneComponent
local PhoneComponent = Class("PhoneComponent", ECSComponent)
local CatDojo = import("Game.Dojo.CatDojo")

function PhoneComponent:__init()
    ECSComponent.__init(self)
    self._cats = {}                    --所有的角色
    self._allTalkContentId = {}          --所有的话题
    self._telephoneQueue =  {}         --来电的队列 处理器
    self._catCurChatsInfo = {}         --和角色的聊天信息记录   本地缓存 key:catId, value:{talkContentId, messageId}
    self._yaoyiyaoChatsInfo = {}       --摇一摇中的聊天信息回复

    self._orderTimes = 0               --累计赠送的点餐次数
    self._useFoodIds = {}             --所有使用过的的食物id
    self.EventOnAppQuit = Events.AddListener(Constants.EventNames.ONAPPQUIT, Bind(self, self.OnAppQuit))
end

function PhoneComponent:__delete()
    self._cats = nil                    --所有的角色
    self._allTalkContentId = {}          --所有的话题
    self._telephoneQueue =  nil         --来电的队列 处理器
    --self._catCurChatsInfo = nil         --和角色的聊天信息记录   本地缓存 key:catId, value:{talkContentId, messageId}
    self._yaoyiyaoChatsInfo = nil  --摇一摇中的聊天信息回复

    self._orderTimes = 0               --累计赠送的点餐次数
    self._useFoodIds = {}           --所有解锁的食物id
end

--初始化所有的话题数据
function PhoneComponent:InitialTalkContent(jsonData)
    jsonData = checkTable(jsonData)
    self._allTalkContentId = {}
    for i, v in pairs(jsonData) do
        self._allTalkContentId[checkString(v)] = 1
    end

    local t = CfUtils.GetLocalData("PHONEMESSAGE")
    if checkString(t) == "0" then
        self._catCurChatsInfo = {}
    else
        self._catCurChatsInfo = checkTable(table.deserialize(t))
    end
    --{}的时候json解出来会是object， 写不回去，这里转一层table
    for k, v in pairs(self._catCurChatsInfo) do
        if v.replyIndexs and table.count(v.replyIndexs) < 1 then
            v.replyIndexs = {}
        end
        --保护一下 纠正本地不正常的数据   直接设nil会重新取
        if checkNumber(v.curMessageId) == 0 or checkNumber(v.curTalkContentId) == 0 then
            self._catCurChatsInfo[k] = nil
        end
    end
end

