---AddPhoneTalkContent 增加一个话题
---@param talkContentId string 话题ID
function PhoneComponent:AddPhoneTalkContentId(talkContentId)
    if checkNumber(talkContentId) == 0 then
        return
    end
    if not self._allTalkContentId then
        self._allTalkContentId = {}
    end

    self._allTalkContentId[checkString(talkContentId)] = 1

    local vo = PhoneUtils.GetPhoneTalkContentVo(talkContentId)
    if vo then
        if checkNumber(vo.topicType) == Constants.PhoneTalkContentType.Telephone and PhoneUtils.IsTalkContentDrivingActive(talkContentId) then
            self:SetTelephone(talkContentId)
        end
        --解锁了的角色才放进来
        if PhoneUtils.IsUnlockCatById(vo.character) then
            GameUtils.UpdateReadPointLocalKey(Constants.RedPointLocalKey.Goodkey, talkContentId, 1)
        end
    end
    PhoneUtils.UpdatePhoneMessageRedPointNum()

    print(table.dump(self._allTalkContentId))
end

---PhoneTopicDoneReq 完成话题
---@param topicId string 话题ID
---@param interactive string 对话顺序，逗号分隔
function PhoneComponent:PhoneTopicDoneReq(topicId, interactive)
    interactive = checkTable(interactive)
    local str = ""
    for k, v in pairs(interactive) do
        if k < #interactive then
            str = str..checkNumber(v)..","
        else
            str = str..checkNumber(v)
        end
    end

    GameUtils.Request(Interfaces.PhoneTopicDone, {topicId = topicId, interactive = str}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local vo = PhoneUtils.GetPhoneTalkContentVo(topicId)
        if vo then
            local catId = checkString(vo.character)
            if checkNumber(catId) ~= 0 then
                local t = self._cats[catId].topic
                if not t then
                    t = {}
                    --t[topicId] = interactive
                    self._cats[catId].topic = t
                --else
                    --t[topicId] = interactive
                end
                table.insert(t, {
                    topicId = checkString(topicId),
                    interactive = interactive,
                })

                PhoneUtils.UpdateCatFavorabilityLevelAndExp(catId, checkNumber(jsonData.favorabilityLevel), checkNumber(jsonData.favorabilityExp), nil, true)
                --清除本地缓存
                self._catCurChatsInfo[checkString(catId)] = nil
                self._catCurChatsInfo[checkString(catId)] = self:GetCatCurChatInfo(catId)
                Events.Broadcast(Constants.EventNames.RefeshChattingInfo, nil)
            end
        end
    end)
end

---PhoneGiveGiftReq 送礼
---@param catId string 角色ID
---@param giftId string 礼物id
---@param giftPackId string 包装id
function PhoneComponent:PhoneGiveGiftReq(catId, giftId, giftPackId, cb)
    GameUtils.Request(Interfaces.PhoneGiveGift, {catId = catId, giftId = giftId, giftPackId = giftPackId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        --local t = self._cats[checkString(catId)]

        local oldLevel, oldExp = PhoneUtils.GetCatFavorabilityLevel(catId)
        PhoneUtils.UpdateCatFavorabilityLevelAndExp(catId, checkNumber(jsonData.favorabilityLevel), checkNumber(jsonData.favorabilityExp), true)
        local dojo = self._cats[checkString(catId)]
        if dojo then
            dojo.leftGiveGiftTimes = checkNumber(dojo.leftGiveGiftTimes) - 1
            --送礼次数加一
            dojo.giveGiftTimes = checkNumber(dojo.giveGiftTimes) + 1
        end

        if cb then
            cb(oldLevel, jsonData.favorabilityLevel)
        end
    end)
end

---PhoneOrderReq 点餐
---@param catId string 角色ID
---@param drinkId string 饮料id
---@param foodId string 食物id
function PhoneComponent:PhoneOrderReq(catId, drinkId, foodId, cb)
    if checkNumber(drinkId) == 0 or checkNumber(foodId) == 0 then
        GameUtils.Toast(localize("请先选择套餐"))
        return
    elseif self._orderTimes >= PhoneUtils.GetMaxOrderTimes() then
        GameUtils.Toast(localize("今日点餐次数已用完"))
        return
    else
        if PhoneUtils.GetOrderConsumeGoodsNum(foodId, drinkId) > GoodsUtils.GetThingNo(PhoneUtils.GetOrderConsumeGoodsId()) then
            GameUtils.Toast(localize("下单所需新海币不足"))
            --[[
            local CookingUtils = import('Game.UI.Phone.Cooking.CookingUtils')
            local vo = CookingUtils.GetOrderFoodVo(drinkId)
            GoodsUtils.CheckConsumeDataCondition({
                {
                    goodsId = vo.coinId,
                    goodsNum = PhoneUtils.GetOrderConsumeGoodsNum(foodId, drinkId),
                }
            })
            ]]
            return
        end

        local dojo = self._cats[checkString(catId)]
        if not dojo then
            GameUtils.Toast(localize("没有该角色"))
            return
        end
        if checkNumber(dojo.leftOrderTimes) < 1 then
            GameUtils.Toast(localize("该角色今日点餐次数已上限"))
            return
        end
    end
    GameUtils.Request(Interfaces.PhoneOrder, {catId = catId, cookingIds = drinkId..","..foodId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data

        local oldLevel, oldExp = PhoneUtils.GetCatFavorabilityLevelAndCurExp(catId)
        PhoneUtils.UpdateCatFavorabilityLevelAndExp(catId, checkNumber(jsonData.favorabilityLevel), checkNumber(jsonData.favorabilityExp), true, nil, true)
        local dojo = self._cats[checkString(catId)]
        if dojo then
            dojo.leftOrderTimes = checkNumber(dojo.leftOrderTimes) - 1
            --点餐次数加一
            self._orderTimes = checkNumber(self._orderTimes) + 1
        end
        self._useFoodIds[checkString(drinkId)] = 1
        self._useFoodIds[checkString(foodId)] = 1

        local CookingUtils = import('Game.UI.Phone.Cooking.CookingUtils')
        local vo = CookingUtils.GetOrderFoodVo(drinkId)
        GoodsUtils.DrawRewards({
            {
                goodsId = vo.coinId,
                num = -PhoneUtils.GetOrderConsumeGoodsNum(foodId, drinkId),
            }
        })

        if cb then
            cb(oldLevel, oldExp, jsonData.favorabilityLevel)
        end
    end)
end

---PhoneDrawFavorabilityRewardReq 领取奖励
---@param catId string 角色ID
---@param rewardId string 奖励id
function PhoneComponent:PhoneDrawFavorabilityRewardReq(catId, rewardId, cb)
    GameUtils.Request(Interfaces.PhoneDrawFavorabilityReward, {catId = catId, rewardId = rewardId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        local dojo = self._cats[checkString(catId)]
