--获取已完成话题的数据
function PhoneComponent:GetCatPassTopicData(topicId)
    local vo = PhoneUtils.GetPhoneTalkContentVo(topicId)
    if not vo then
        return nil
    end

    local catDojo = self:GetCatDataById(checkString(vo.character))
    if not catDojo then
        return nil
    end

    local topics = catDojo.topic
    if topics then
        for k, v in pairs(topics) do
            if checkNumber(v.topicId) == checkNumber(topicId) then
                return v
            end
        end
    end
    return nil
end

---SendTalkContentId 发送一个话题
---@param catId string 角色id
---@param talkContentId string 话题id
---@param messageId string 信息id   这里只穿默认的第一条信息id
function PhoneComponent:SendTalkContentId(catId, talkContentId, messageId)
    if checkNumber(catId) == 0 or checkNumber(talkContentId) == 0 then
        return false
    end

    --信息id直接默认赋值第一个
    self._catCurChatsInfo[checkString(catId)] = {
        curTalkContentId = talkContentId,
        curMessageId = messageId,            --当前的信息id
        replyIndexs = {},                        --回复的下标数组
    }
    return true
end

---SendMessageId 发送一个消息
---@param catId string @ 角色id
---@param messageId integer @ 发送的信息id
---@param replyData integer @ 回复的选择数据
function PhoneComponent:SendMessageId(catId, messageId, replyData)
    local t = self._catCurChatsInfo[checkString(catId)]
    if not t then
        return
    end

    --如果最新的消息有回复 取回复数据
    if PhoneUtils.IsMessageHasSelections(t.curMessageId) then
        if replyData then
            if t.replyIndexs then
                table.insert(t.replyIndexs, checkNumber(replyData.index))
                local messageId = PhoneUtils.GetMessageIdByTargetId(t.curTalkContentId, checkString(replyData.targetId))
                t.curMessageId = messageId
            end
        end
    else
        if checkNumber(messageId) ~= 0 then
            t.curMessageId = checkString(messageId)
        end
    end

    --如果是信息结束
    if PhoneUtils.IsMessageIsEnd(t.curMessageId) then
        self:PhoneTopicDoneReq(t.curTalkContentId, t.replyIndexs)
    end
end

---IsPassTalkContent 改话题是否已完成
---@param topicId string 话题id
function PhoneComponent:IsPassTalkContent(topicId)
    local vo = PhoneUtils.GetPhoneTalkContentVo(topicId)
    if not vo then
        return false
    end
    local t = self:GetCatDataById(checkString(vo.character))
    if not t then
        return false
    end

    local topics = t.topic
    if topics then
        for k, v in pairs(topics) do
            if checkNumber(v.topicId) == checkNumber(topicId) then
                return true
            end
        end
    end
    return false
end

---IsUnlockTalkContent 改话题是否已拥有
---@param talkContentId string 话题id
function PhoneComponent:IsUnlockTalkContent(talkContentId)
    if not self._allTalkContentId then
        return false
    end

    return checkNumber(self._allTalkContentId[checkString(talkContentId)]) == 1
end

---GetCatCurChatInfo 获取角色当前的对话信息
---@param catId string 角色id
function PhoneComponent:GetCatCurChatInfo(catId)
    local t = self._catCurChatsInfo[checkString(catId)]
    if not t then
        local ids = PhoneUtils.GetTalkContentIds(catId, Constants.PhoneTalkContentType.Message)
        if not ids or table.count(ids) <= 0 then
            return
        end
        for k, v in pairs(ids) do
            --是主动解锁 且 已解锁 未完成
            if PhoneUtils.IsTalkContentDrivingActive(v) and self:IsUnlockTalkContent(v) and not self:IsPassTalkContent(v) then
                local messageIds = PhoneUtils.GetTalkIds(checkString(v))
                if messageIds and table.count(messageIds) > 0 then
                    t = {
                        curTalkContentId = v,
                        curMessageId = PhoneUtils.GetStopMessageId(PhoneUtils.GetTalkCountFirstId(v)),            --当前的信息id
                        replyIndexs = {},                        --回复的下标数组
                    }
                    self:SendTalkContentId(catId, v, t.curMessageId)
                    Events.Broadcast(Constants.EventNames.RefeshChattingInfo, nil)
                end
            end
        end
    end

    return t
end

--更新当前对话信息
function PhoneComponent:UpdateCatCurChatInfo(catId, topicId, messageId, replyIndexs)
    catId = checkNumber(catId)
    if catId == 0 then
        return
    end
    local t = self._catCurChatsInfo[checkString(catId)]
    if not t then
        return
    end

    if checkNumber(topicId) ~= 0 then
        t.curTalkContentId = checkString(topicId)
    end
    if checkNumber(messageId) ~= 0 then
        t.curMessageId = checkString(messageId)
    end
    if replyIndexs then
        t.replyIndexs = checkTable(replyIndexs)
    end
end

---UpdateGiveGiftNum 刷新送礼次数  月卡用
function PhoneComponent:UpdateGiveGiftNum(isTrue)
    if not self._cats then
        return
    end
    local storeComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.StoreComponent)
    local StoreConstants = import('Game.UI.Store.StoreConstants')
    
    for k, v in pairs(self._cats) do
        local maxNum = PhoneUtils.GetAllGiveGiftNum()
        if isTrue then
            v.leftGiveGiftTimes = ((v.leftGiveGiftTimes + checkNumber(storeComp:GetMonthCardPrivilege(StoreConstants.MonthCardPrivileges.GiftNum))) > maxNum and maxNum or v.leftGiveGiftTimes + checkNumber(storeComp:GetMonthCardPrivilege(StoreConstants.MonthCardPrivileges.GiftNum)))
        else
            v.leftGiveGiftTimes = v.leftGiveGiftTimes - checkNumber(storeComp:GetMonthCardPrivilege(StoreConstants.MonthCardPrivileges.GiftNum))
        end
    end
end

