end

--取出一个电话
function PhoneComponent:GetTelephoneId()
    if self._telephoneQueue and table.count(self._telephoneQueue) > 0 then
        local id = self._telephoneQueue[1]
        table.remove(self._telephoneQueue, 1)
        return id
    end
    return nil
end

