--获取当前的点餐次数
function PhoneComponent:GetCurOrderTimes()
    return checkNumber(self._orderTimes)
end

function PhoneComponent:IsMaxLevel(level)
    if not self._maxLevel then
        local t = CfUtils.GetCfTable(AutoIds.IdSetting864)
        if t then
            local num = 0
            for k, v in pairs(t) do
                local id = parse_number(v, "rankId")
                if id > num then
                    num = id
                end
            end
            self._maxLevel = num
        end
    end
    return checkNumber(level) >= checkNumber(self._maxLevel)
end

--是否使用过食物
function PhoneComponent:IsUseFood(id)
    if not self._useFoodIds then
        return false
    end
    return checkNumber(self._useFoodIds[checkString(id)]) == 1
end

return PhoneComponent